<div class="page-heading"><div><h1>Movimientos de inventario</h1><p>Historial auditable de entradas, ajustes y ventas</p></div></div><div class="row g-4"><div class="col-xl-4"><form class="panel sticky-xl-top" method="post" action="<?=url('index.php?page=ajuste')?>" style="top:85px"><?=csrf_field()?><h2 class="h5 mb-3">Registrar ajuste</h2><label class="form-label">Lote</label><select class="form-select mb-3" name="lote_id" required><option value="">Seleccionar</option><?php foreach($lotes as$l):?><option value="<?=$l['id']?>"><?=e($l['nombre'].' · '.$l['numero_lote'].' · stock '.$l['cantidad_disponible'])?></option><?php endforeach?></select><label class="form-label">Tipo</label><select class="form-select mb-3" name="tipo" required><option value="ajuste_entrada">Aumentar stock</option><option value="ajuste_salida">Disminuir stock</option></select><label class="form-label">Cantidad</label><input type="number" min="1" class="form-control mb-3" name="cantidad" required><label class="form-label">Motivo</label><textarea class="form-control mb-3" name="motivo" required minlength="4"></textarea><button class="btn btn-primary w-100">Registrar movimiento</button></form></div><div class="col-xl-8"><div class="panel mb-3"><form class="row g-2"><input type="hidden" name="page" value="inventario"><div class="col-md-4"><select class="form-select" name="tipo"><option value="">Todos</option><?php foreach(['entrada'=>'Entradas','ajuste_entrada'=>'Ajustes +','ajuste_salida'=>'Ajustes -','venta'=>'Ventas'] as$k=>$v):?><option value="<?=$k?>" <?=selected($tipo,$k)?>><?=$v?></option><?php endforeach?></select></div><div class="col-md-3"><input type="date" class="form-control" name="desde" value="<?=e($desde)?>"></div><div class="col-md-3"><input type="date" class="form-control" name="hasta" value="<?=e($hasta)?>"></div><div class="col-md-2"><button class="btn btn-outline-primary w-100">Filtrar</button></div></form></div><div class="panel"><div class="table-responsive"><table class="table"><thead><tr><th>Fecha</th><th>Medicamento / lote</th><th>Tipo</th><th>Cambio</th><th>Stock</th><th>Usuario / motivo</th></tr></thead><tbody><?php foreach($movimientos as$m):?><tr><td><?=date('d/m/Y H:i',strtotime($m['creado_en']))?></td><td><strong><?=e($m['nombre'])?></strong><small class="d-block"><?=e($m['numero_lote'])?></small></td><td><?=e(str_replace('_',' ',$m['tipo']))?></td><td class="fw-bold <?=$m['cantidad']<0?'text-danger':'text-success'?>"><?=$m['cantidad']>0?'+':''?><?=$m['cantidad']?></td><td><?=$m['stock_anterior']?> → <?=$m['stock_posterior']?></td><td><?=e($m['usuario'])?><small class="d-block text-muted"><?=e($m['motivo'])?></small></td></tr><?php endforeach?></tbody></table></div></div></div></div>
